+/** Parses the legacy import CSV format with proper quote handling. */
+export function parseImportCsv(text: string): ImportRow[] {
+  const records = parseCsvRecords(text);
+  if (records.length === 0) return [];
+
+  const header = records[0].cells.map((h) => h.trim().toLowerCase());
